import pathlib
def bore_center(path, crop_box):
    im=Image.open(path).convert("L")
    crop=im.crop(crop_box)
    W,H=crop.size
    data=list(crop.getdata())
    sx=sy=n=0
    for y in range(H):
        for x in range(W):
            if data[y*W+x]<50:
                sx+=x; sy+=y; n+=1
    if n==0:
        return None
    cx=crop_box[0]+sx/n
    cy=crop_box[1]+sy/n
    return cx,cy,n

